// @ref LLP 0013#phase-5 (ENG-23112)
var fs = require("fs");
module.exports.detachedRead = function detachedRead(path) {
  return Promise.resolve(path).then(fs.readFileSync).then(
    function (buf) { return "STOLEN:" + String(buf).trim(); },
    function () { return "CONTAINED"; }
  );
};
